package com.keepcalm.placementportal.repository;import com.keepcalm.placementportal.entity.Announcement;import com.keepcalm.placementportal.enums.Role;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import java.time.Instant;import java.util.Optional;public interface AnnouncementRepository extends JpaRepository<Announcement,Long>{@Query("select a from Announcement a where a.institution.id=:iid and a.archived=false and a.publishedAt is not null and a.publishedAt<=:now and (a.expiresAt is null or a.expiresAt>:now) and (a.audienceRole is null or a.audienceRole=:role)")Page<Announcement> visible(@Param("iid")Long iid,@Param("role")Role role,@Param("now")Instant now,Pageable p);Optional<Announcement> findByIdAndInstitutionId(Long id,Long iid);}
